from contextlib import contextmanager


class System:
    def __init__(self):
        self.status = 'normal'


@contextmanager
def maintenance_mode(system, log):
    log.append('entering maintenance')
    system.status = 'maintenance'
    try:
        yield
    finally:
        system.status = 'normal'
        log.append('exiting maintenance')
